{"thought": "I will try to write the implementation again, but I'll make it much more concise to avoid truncation and ensure the JSON is valid. I'll use a slightly different approach to building the results to keep the code short.", "action": {"tool": "write_file", "args": {"path": "src/stockflow/cycle_count_variance.py", "content": "from __future__ import annotations

from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Set, Tuple, Union
from stockflow.on_hand_by_location import on_hand_by_location
from stockflow.normalize_sku import normalize_sku
from stockflow.parse_location import parse_location


def cycle_count_variance(
    lines: Iterable[str], 
    case_sizes: Mapping[str, int], 
    counts: Mapping[Tuple[str, str], int]
) -> List[Tuple[str, str, int]]:
    """
    Compare a cycle count with system stock and report the differences.
    """
    def to_loc_str(loc_tuple: Tuple[Any, ...]) -> str:
        z, a, s, l = loc_tuple
        return f"{z}-{a:02d}-{s:02d}-{l}"

    counts_agg: Dict[Tuple[str, Tuple[Any, ...]], int] = {}
    for (r_sku, r_loc), qty in counts.items():
        if qty < 0: raise ValueError("Negative quantity")
        k = (normalize_sku(r_sku), parse_location(r_loc))
        counts_agg[k] = counts_agg.get(k, 0) + qty

    sys_raw = on_hand_by_location(lines, case_sizes)
    sys_agg: Dict[Tuple[str, Tuple[Any, ...]], int] = {}
    for (sku, loc_str), qty in sys_raw.items():
        k = (sku, parse_location(loc_str))
        sys_agg[k] = sys_agg.get(k, 0) + qty

    all_keys = set(counts_agg.keys()) | set(sys_agg.keys())
    results = []
    for sku, loc_tup in all_keys:
        v = counts_agg.get((sku, loc_tup), 0) - sys_agg.get((sku, loc_tup), 0)
        if v != 0:
            results.append((sku, to_loc_str(loc_tup), v))

    # Sort by location string, then SKU
    return sorted(results, key=lambda x: (x[1], x[0]))
"}}, "messages": []}

